import{_ as t,o,c as a,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const p=JSON.parse('{"title":"Plan — FR 3.4.1: List Agency","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/03-agency-workspace/3-4-1-list-agency/plan.md","filePath":"feature/srs/03-agency-workspace/3-4-1-list-agency/plan.md"}'),r={name:"feature/srs/03-agency-workspace/3-4-1-list-agency/plan.md"};function n(s,e,d,i,l,g){return o(),a("div",null,[...e[0]||(e[0]=[c('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-4-1-list-agency" tabindex="-1">Plan — FR 3.4.1: List Agency <a class="header-anchor" href="#plan-—-fr-3-4-1-list-agency" aria-label="Permalink to &quot;Plan — FR 3.4.1: List Agency&quot;">​</a></h1><p>&gt; Implements <a href="./spec.html">spec.md</a> for canonical roles <code>Owner, Manager, Creator, Client, Admin</code> enforcing <code>BR-15, BR-20</code>.</p><h2 id="_1-technical-component-map" tabindex="-1">1. Technical Component Map <a class="header-anchor" href="#_1-technical-component-map" aria-label="Permalink to &quot;1. Technical Component Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Repository / Package</th><th style="text-align:left;">Concrete Classes &amp; Files</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>API Gateway</strong></td><td style="text-align:left;"><code>brandhub-api-gateway</code></td><td style="text-align:left;"><code>JwtAuthFilterGatewayFilterFactory.java</code>, <code>InboundSecurityWebFilter.java</code>, <code>GatewayConfig.java</code> (<code>/api/v1/**</code>)</td></tr><tr><td style="text-align:left;"><strong>Controller</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>AgencyController.listMyAgencies()</code></td></tr><tr><td style="text-align:left;"><strong>Service</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>AgencyServiceImpl.listMyAgencies()</code></td></tr><tr><td style="text-align:left;"><strong>Repositories</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;">AgencyRepository (<code>findByOwnerIdAndStatusNot</code>), AgencyMemberRepository (<code>findByUserId</code>)</td></tr><tr><td style="text-align:left;"><strong>Security / ACL</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>RequireRoleAspect.java</code>, <code>WorkspaceIsolationHelper.java</code>, <code>WorkspaceAccessService.java</code></td></tr><tr><td style="text-align:left;"><strong>Web Frontend</strong></td><td style="text-align:left;"><code>brandhub-web</code></td><td style="text-align:left;"><code>src/pages/agency/index.tsx</code>, <code>src/pages/agency/components/hub/{AgencyHubCard,SegmentedHubSwitcher,AgencyQuickFilterPills}.tsx</code>, <code>src/components/layout/sidebar/OrgSwitcherDropdown.tsx</code>, <code>src/services/agencyService.ts</code></td></tr><tr><td style="text-align:left;"><strong>Mobile App</strong></td><td style="text-align:left;"><code>brandhub-mobile-app</code></td><td style="text-align:left;"><code>src/screens/workspace/WorkspacePickerScreen.tsx</code>, <code>src/services/agencyService.ts</code>, <code>src/store/workspaceStore.ts</code></td></tr></tbody></table><h2 id="_2-data-model-schema-indexes" tabindex="-1">2. Data Model, Schema &amp; Indexes <a class="header-anchor" href="#_2-data-model-schema-indexes" aria-label="Permalink to &quot;2. Data Model, Schema &amp; Indexes&quot;">​</a></h2><ul><li><strong>Primary Stores:</strong> PostgreSQL <code>agencies</code>, <code>agency_members</code>.</li><li><strong>Key Architectural Details:</strong><ul><li>Combines owned Agencies (<code>owner_id = userId</code>) and joined Agencies (<code>agency_members.user_id = userId</code>) in a deterministic <code>LinkedHashSet</code>, filtering out <code>EntityStatus.SOFT_DELETED</code> rows so soft-deleted Agencies never leak through residual membership rows.</li><li><strong>Multi-Tenant Indexing:</strong> Foreign-key and composite lookup indexes on <code>agencies(owner_id, status)</code>, <code>agency_members(agency_id, user_id)</code>, <code>workspaces(agency_id, status)</code>, <code>workspace_members(workspace_id, user_id, is_active)</code>, and <code>workspace_invitations</code> / <code>agency_invitations(token, status, expires_at)</code> ensure single-digit millisecond ACL and listing queries.</li><li><strong>Canonical Timezone Source:</strong> Workspace timezone reads/writes use <code>workspaces.timezone_config</code> (default <code>Asia/Ho_Chi_Minh</code>) mirrored cleanly in <code>WorkspaceResponse.settings.timezone</code>.</li></ul></li></ul><h2 id="_3-end-to-end-execution-flow" tabindex="-1">3. End-to-End Execution Flow <a class="header-anchor" href="#_3-end-to-end-execution-flow" aria-label="Permalink to &quot;3. End-to-End Execution Flow&quot;">​</a></h2><ol><li><strong>Client Invocation:</strong> Authorized actor (<code>Owner, Manager, Creator, Client, Admin</code>) initiates <strong>List Agency</strong> from <code>src/pages/agency/index.tsx</code>, <code>src/pages/agency/components/hub/{AgencyHubCard,SegmentedHubSwitcher,AgencyQuickFilterPills}.tsx</code>, <code>src/components/layout/sidebar/OrgSwitcherDropdown.tsx</code>, <code>src/services/agencyService.ts</code> (Web) or <code>src/screens/workspace/WorkspacePickerScreen.tsx</code>, <code>src/services/agencyService.ts</code>, <code>src/store/workspaceStore.ts</code> (Mobile).</li><li><strong>Gateway &amp; Principal Resolution:</strong> <code>brandhub-api-gateway</code> validates Bearer JWT signature and Redis blacklist status (<code>jwt:blacklist:{jti}</code>), forwarding <code>X-Request-Id</code> and principal headers to <code>brandhub-business-service</code>.</li><li><strong>Authorization &amp; Business Rule Validation:</strong> <code>AgencyController.listMyAgencies()</code> validates DTO constraints (<code>@Valid</code>) and delegates to <code>AgencyServiceImpl.listMyAgencies()</code>, which verifies live DB role/ownership (<code>Owner, Manager, Creator, Client, Admin</code>) and domain rules (<code>BR-15, BR-20</code>).</li><li><strong>Atomic Persistence / Aggregation:</strong> Executes <code>@Transactional</code> queries/updates across PostgreSQL <code>agencies</code>, <code>agency_members</code>, mapping domain violations deterministically to <code>401 UNAUTHORIZED</code> (<code>MSG22</code>).</li><li><strong>Client State Synchronization:</strong> Returns <code>ApiResponse&lt;T&gt;</code>; frontend invalidates scoped TanStack Query keys (<code>agency</code> / <code>workspaces</code> / <code>dashboard</code>), updates Zustand active org/workspace context when applicable, and renders localized (<code>agency.list.* / agency.hub.*</code>) feedback.</li></ol><h2 id="_4-security-concurrency-operational-guards" tabindex="-1">4. Security, Concurrency &amp; Operational Guards <a class="header-anchor" href="#_4-security-concurrency-operational-guards" aria-label="Permalink to &quot;4. Security, Concurrency &amp; Operational Guards&quot;">​</a></h2><ul><li><strong>Zero Client-Trusted Role Claims:</strong> Every Workspace/Agency check re-queries PostgreSQL (<code>agency.ownerId</code> or active <code>workspace_members</code> row via <code>@RequireRoleAspect</code> / <code>WorkspaceAccessService</code>) so revoked members lose access immediately without waiting for JWT expiry.</li><li><strong>Race-Condition Protection:</strong> Database uniqueness constraints (<code>UNIQUE(agency_id, user_id)</code>, active single-Manager check, idempotent <code>duplication_request_id</code>, and atomic invitation status transitions) prevent duplicate records on double-clicks or concurrent admin actions.</li><li><strong>No Mock Fallback in Production:</strong> Empty lists and backend errors render explicit localized empty/retry states rather than synthetic placeholder rows.</li></ul><h2 id="_5-cross-references" tabindex="-1">5. Cross-References <a class="header-anchor" href="#_5-cross-references" aria-label="Permalink to &quot;5. Cross-References&quot;">​</a></h2><ul><li><strong>Specification &amp; Test Suite:</strong> <a href="./spec.html">spec.md</a> · <a href="./task.html">task.md</a> · <a href="./test.html">test.md</a></li><li><strong>BA &amp; Architecture Docs:</strong> <a href="./../../../../ba/03-agency-workspace.html">03-agency-workspace.md</a> · <a href="./../../../modules/README.html">Module Specs Index</a></li></ul><h2 id="endpoint-authorization-error-mapping-matrix" tabindex="-1">Endpoint, Authorization &amp; Error Mapping Matrix <a class="header-anchor" href="#endpoint-authorization-error-mapping-matrix" aria-label="Permalink to &quot;Endpoint, Authorization &amp; Error Mapping Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Aspect</th><th style="text-align:left;">Specification</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR / Feature</strong></td><td style="text-align:left;"><code>FR 3.4.1</code> — List Agency</td></tr><tr><td style="text-align:left;"><strong>HTTP / WS Endpoints</strong></td><td style="text-align:left;"><code>GET /api/v1/agencies</code></td></tr><tr><td style="text-align:left;"><strong>Authorized Canonical Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Controller -&gt; Service</strong></td><td style="text-align:left;"><code>AgencyController.listMyAgencies()</code> -&gt; <code>AgencyServiceImpl.listMyAgencies()</code></td></tr><tr><td style="text-align:left;"><strong>Persistence / Cache Targets</strong></td><td style="text-align:left;">PostgreSQL <code>agencies</code>, <code>agency_members</code></td></tr><tr><td style="text-align:left;"><strong>Business Rule Invariants</strong></td><td style="text-align:left;"><code>BR-15, BR-20</code></td></tr><tr><td style="text-align:left;"><strong>Error Code Contract</strong></td><td style="text-align:left;"><code>401 UNAUTHORIZED</code> (<code>MSG22</code>)</td></tr></tbody></table><h2 id="frontend-cache-i18n-theme-architecture" tabindex="-1">Frontend Cache, i18n &amp; Theme Architecture <a class="header-anchor" href="#frontend-cache-i18n-theme-architecture" aria-label="Permalink to &quot;Frontend Cache, i18n &amp; Theme Architecture&quot;">​</a></h2><ul><li><strong>Web State &amp; Query Management (<code>brandhub-web</code>):</strong><ul><li>Components &amp; Hooks: <code>src/pages/agency/index.tsx</code>, <code>src/pages/agency/components/hub/{AgencyHubCard,SegmentedHubSwitcher,AgencyQuickFilterPills}.tsx</code>, <code>src/components/layout/sidebar/OrgSwitcherDropdown.tsx</code>, <code>src/services/agencyService.ts</code>.</li><li>Query Keys &amp; Cache Invalidation: Scoped by authenticated <code>userId</code>, <code>agencyId</code>, or <code>workspaceId</code> so switching tenants or logging out never leaks cached records across boundaries.</li><li>Conflict &amp; Error Recovery: Preserves in-progress user form state on <code>400</code>/<code>409</code> responses, disables duplicate in-flight submissions, and never falls back to hardcoded mock data.</li></ul></li><li><strong>Mobile Parity (<code>brandhub-mobile-app</code>):</strong><ul><li>Screens &amp; Services: <code>src/screens/workspace/WorkspacePickerScreen.tsx</code>, <code>src/services/agencyService.ts</code>, <code>src/store/workspaceStore.ts</code>.</li><li>Uses shared REST/WS contract, <code>expo-secure-store</code> Bearer token injection, and mobile <code>workspaceStore</code> / <code>authStore</code> synchronization.</li></ul></li><li><strong>Localization &amp; Theme Standards:</strong><ul><li>Key-parallel Vietnamese (<code>vi</code>) and English (<code>en</code>) locale entries under <code>agency.list.* / agency.hub.*</code> with zero hardcoded strings.</li><li>Semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useTheme()</code> semantic tokens on Mobile verified across Light and Dark modes.</li></ul></li><li><strong>Observability &amp; Audit Correlation:</strong><ul><li>Propagates <code>X-Request-Id</code> from <code>brandhub-api-gateway</code> into <code>ApiResponse.requestId</code> and structured backend logs / <code>audit_logs</code> where security-sensitive mutations occur.</li></ul></li><li><strong>BA &amp; Module Traceability:</strong> <a href="./../../../../ba/03-agency-workspace.html">BA Domain Spec</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a>.</li></ul>',17)])])}const h=t(r,[["render",n]]);export{p as __pageData,h as default};
